 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}

    # When a complete stripe is the reference, color the missing portion of
    # its partial repetitions with 1.
    for color in colors:
        full = any(all(v == color for v in row) for row in grid)
        if full:
            for r, row in enumerate(grid):
                if color in row and any(v == bg for v in row):
                    for c, v in enumerate(row):
                        if v == bg:
                            out[r][c] = 1

    # Repeated multi-row motifs: later copies may have the reference motif's
    # foreground cells replaced by background; mark those replaced cells 1.
    # Use the initial contiguous non-background block as the reference.
    active = [any(v != bg for v in row) for row in grid]
    if active and active[0]:
        end = 0
        while end < h and active[end]:
            end += 1
        n = end
        if n >= 2 and n * 2 <= h:
            ref = grid[:n]
            for start in range(n + 1, h - n + 1):
                # Only treat a block as a copy when each row preserves all
                # non-background structure except for omissions to bg.
                valid = True
                for i in range(n):
                    for c in range(w):
                        if ref[i][c] != bg and grid[start+i][c] not in (ref[i][c], bg):
                            valid = False
                        elif ref[i][c] == bg and grid[start+i][c] != bg:
                            valid = False
                if valid and any(any(v != bg for v in grid[start+i]) for i in range(n)):
                    for i in range(n):
                        for c in range(w):
                            if ref[i][c] != bg and grid[start+i][c] == bg:
                                out[start+i][c] = 1
    return out
